#!/usr/bin/env python3
# AI DISCLAIMER: All of the text in this file was generated by AI.
"""Score a fastbox window with any number of arms: per arm the median [min-max] of wall_s, cpu_s, peak_anon_MB and
post_idle_anon_MB over its runs (results.csv[.gz] written by fb_window.sh), then each requested pair as the ratio of
medians, marked "no overlap" when the two arms' ranges are disjoint. Runs whose hash_match is not "yes" are listed
and left out.
usage: fastbox_pairs.py <window dir> <arm>/<baseline arm> [...]      e.g. fastbox_pairs.py out/heavy Cp/A CpTW/Cp
"""
import csv, gzip, os, statistics, sys

d = sys.argv[1]; pairs = [p.split("/") for p in sys.argv[2:]]
p = os.path.join(d, "results.csv")
rows = list(csv.DictReader(open(p) if os.path.exists(p) else gzip.open(p + ".gz", "rt")))
M = ["wall_s", "cpu_s", "peak_anon_MB", "post_idle_anon_MB"]
arms = {}
for r in rows:
    if r.get("hash_match") != "yes":
        print("left out: round %s arm %s hash_match=%s" % (r["round"], r["arm"], r.get("hash_match")))
        continue
    arms.setdefault(r["arm"], []).append({m: float(r[m]) for m in M})
print("%-6s %3s  %s" % ("arm", "n", "  ".join("%-24s" % m for m in M)))
for a in sorted(arms):
    v = arms[a]
    print("%-6s %3d  %s" % (a, len(v), "  ".join("%-24s" % ("%.0f [%.0f-%.0f]" % (statistics.median(x[m] for x in v), min(x[m] for x in v), max(x[m] for x in v))) for m in M)))
for a, b in pairs:
    if a not in arms or b not in arms:
        print("%s/%s: missing arm" % (a, b)); continue
    out = []
    for m in M:
        va = [x[m] for x in arms[a]]; vb = [x[m] for x in arms[b]]
        r = statistics.median(va) / statistics.median(vb)
        disjoint = max(va) < min(vb) or min(va) > max(vb)
        out.append("%s %.3f (%+.1f%%, %s)" % (m, r, 100 * (r - 1), "no overlap" if disjoint else "overlap"))
    print("%s/%s: %s" % (a, b, "; ".join(out)))
